<?php
namespace davvag_events;

require_once dirname(__DIR__,2).'/lib/bootstrap.php';

final class SalesService extends Service {
    public function getTypes($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');Domain::gate($e);Domain::publicView($e);$types=[];foreach($e['ticketTypes'] as $t){$t['remaining']=max(0,min($t['capacity']-Ticketing::typeUsed($e,$t['id']),$e['published']['capacity']-Domain::occupancy($e)));$t['enabled']=$t['price']===0||Stripe::configured();$types[]=$t;}return ['types'=>$types];}); }
    public function postSaveType($req,$res) { return $this->run($req,$res,function($in){$r=Store::mutate($in['eventId']??'',Identity::actor(),'payments',function(&$e)use($in){return Ticketing::type($e,$in);},$in['revision']??null);return $r['value'];},true); }
    public function postCheckout($req,$res) { return $this->run($req,$res,function($in){$id=$in['eventId']??'';Store::limit($id,'checkout',10);$e=Store::load($id);Domain::gate($e);$party=null;try{$party=Domain::capability($e,'rsvp')['reference'];}catch(Fault $f){if($e['published']['privacy']==='private')throw $f;}$rev=$e['revision'];$order=Ticketing::order($e,$in,$party);Store::save($e,$rev,'guest','checkout_reserve');
            if($order['amount']>0&&empty($order['checkoutUrl'])){$session=Stripe::create($e,$order);$fresh=Store::load($id);$rev=$fresh['revision'];foreach($fresh['orders'] as &$o)if($o['id']===$order['id']){$o['sessionId']=$session['id'];$o['checkoutUrl']=$session['url'];if($o['status']==='holding')$o['status']='checkout';$order=$o;}unset($o);Store::save($fresh,$rev,'provider','checkout_created');}
            return ['id'=>$order['id'],'status'=>$order['status'],'checkoutUrl'=>$order['checkoutUrl'],'retrieval'=>$order['retrieval']??null];},true); }
    public function postDisplayTickets($req,$res) { return $this->run($req,$res,function($in){Store::limit($in['eventId']??'','ticket_display',15);$e=Store::load($in['eventId']??'');$i=Ticketing::orderAccess($e,$in['orderId']??'',$in['retrieval']??null);$rev=$e['revision'];$v=Ticketing::display($e,$i);if($e['orders'][$i]['amount']>0&&in_array($v['status'],['holding','checkout','expired'],true))Jobs::enqueue($e,'payment',$v['id'],'redisplay-'.$v['id'].'-'.gmdate('YmdHi'));Store::save($e,$rev,'order:'.$v['id'],'ticket_redisplay');return $v;},true); }
    public function postAdmission($req,$res) { return $this->run($req,$res,function($in){Store::limit($in['eventId']??'','admission_view',15);$e=Store::load($in['eventId']??'');$a=Admission::resolve($e,$in['admission']??'');return ['name'=>$a['guest']['name'],'status'=>'issued','event'=>$e['published']['title']??$e['draft']['title'],'notice'=>'Present this code to staff. Viewing it does not check you in.'];},true); }
    public function postRefund($req,$res) { return $this->run($req,$res,function($in){$r=Store::mutate($in['eventId']??'',Identity::actor(),'payments',function(&$e)use($in){$reason=Support::text($in['reason']??'',500,true);foreach($e['orders'] as $o)if($o['id']===($in['orderId']??'')){if($o['amount']===0){Ticketing::revoke($e,$o['id'],'cancelled');return ['status'=>'cancelled'];}Ticketing::revoke($e,$o['id'],'refund_pending');Jobs::enqueue($e,'refund',$o['id'],'refund-'.$o['id']);$e['audit'][]=['id'=>Support::id(),'actor'=>Identity::actor()['id'],'action'=>'refund_requested','reference'=>$o['id'],'reason'=>$reason,'at'=>Support::now()];return ['status'=>'refund_pending'];}Support::fail('ORDER','Order not found.',404);});return $r['value'];},true); }
}
